/// <summary>
///    The <c>METCustomerStatusChangeBusinessEvent</c> class extends <c>BusinessEventsBase</c> to provide customer status change business event.
/// </summary>
[BusinessEvents(classStr(METCustomerStatusChangeBusinessEventContract),
    "@MET:CustomerStatusChangeBusinessEventName",
    "@MET:CustomerStatusChangeBusinessEventDesc",
    ModuleAxapta::Customer)]
public final class METCustomerStatusChangeBusinessEvent extends BusinessEventsBase
{
    private CustTable custTable;
       
}

Method.Source:
    /// <summary>
    /// Constructs a new METCustomerStatusChangeBusinessEvent business event.
    /// </summary>
    /// <param name = "_custTable">The <c>CustTablee</c> record.</param>
    /// <returns>A new <c>METCustomerStatusChangeBusinessEvent</c> business event.</returns>
    public static METCustomerStatusChangeBusinessEvent construct(CustTable _custTable)
    {
        var event = new METCustomerStatusChangeBusinessEvent();
        event.parmCustTable(_custTable);

        return event;
    }

    private CustTable parmCustTable(CustTable _custTable = custTable)
    {
        custTable = _custTable;

        return custTable;
    }

/// <summary>
/// Overrides to provide customer status change data.
/// </summary>
/// <returns>The <c>METCustomerStatusChangeBusinessEventContract</c> of the event.</returns>
public BusinessEventsContract buildContract()
{
    var contract = METCustomerStatusChangeBusinessEventContract::construct();
    contract.parmLegalEntity(curExt());
    contract.parmCustomerAccount(custTable.AccountNum);
    contract.parmCustomerStatus(custTable.CredManAccountStatusId);
    
    return contract;
}

/// <summary>
/// Gets the record context for this event.
/// </summary>
/// <returns>The <c>CustTable</c> buffer for the record context for this event.</returns>
public Common getContextRecord()
{
    return this.parmCustTable();
}
